components.css:
.ds-field { display: grid; gap: 4px; }
.ds-field-label { font-family: 'Source Sans 3', system-ui, sans-serif; font-size: 0.6875rem; font-weight: 600; letter-spacing: 0.14em; text-transform: uppercase; color: #5f6d75; }
.ds-field-control { position: relative; }
.ds-field-icon { position: absolute; left: 12px; top: 50%; transform: translateY(-50%); width: 16px; height: 16px; color: #5f6d75; pointer-events: none; }
.ds-input { width: 100%; height: 36px; padding: 0 12px 0 36px; border: 1px solid #ccd3d1; border-radius: 7px; background: #ffffff; color: #172b3a; font-family: 'Source Sans 3', system-ui, sans-serif; font-size: 0.875rem; transition: border-color 200ms cubic-bezier(0.22, 1, 0.36, 1), box-shadow 200ms cubic-bezier(0.22, 1, 0.36, 1); }
.ds-input::placeholder { color: #5f6d75; }
.ds-input:hover { border-color: #c3d9d6; }
.ds-input:focus-visible { outline: none; border-color: #24676b; box-shadow: 0 0 0 2px rgb(36 103 107 / 0.3); }

.ds-record { padding: 24px; border: 1px solid #e1e5e4; border-radius: 8px; background: #ffffff; }
.ds-record-label { margin: 0; font-family: 'Source Sans 3', system-ui, sans-serif; font-size: 0.6875rem; font-weight: 600; letter-spacing: 0.14em; text-transform: uppercase; color: #5f6d75; }
.ds-record-list { margin: 16px 0 0; display: grid; gap: 12px; }
.ds-record-row { padding-top: 12px; border-top: 1px solid #e1e5e4; }
.ds-record-row:first-child { padding-top: 0; border-top: 0; }
.ds-record-row dt { font-family: 'Source Sans 3', system-ui, sans-serif; font-size: 0.75rem; letter-spacing: 0.06em; text-transform: uppercase; color: #5f6d75; }
.ds-record-row dd { margin: 4px 0 0; font-family: 'Source Sans 3', system-ui, sans-serif; font-size: 0.875rem; font-weight: 500; line-height: 1.35; color: #172b3a; }

.ds-row { display: grid; grid-template-columns: 2.25rem minmax(0, 1fr) auto; gap: 0 24px; align-items: start; padding: 20px 0; border-bottom: 1px solid #e1e5e4; font-family: 'Source Sans 3', system-ui, sans-serif; }
.ds-row-num { font-family: 'Source Serif 4', Georgia, serif; font-size: 0.875rem; line-height: 1.75rem; color: #5f6d75; }
.ds-row-title { margin: 0; font-family: 'Source Serif 4', Georgia, serif; font-size: 1.3125rem; font-weight: 600; line-height: 1.3; color: #102a3a; }
.ds-row-authors { margin: 8px 0 0; font-size: 0.9375rem; color: #55636b; }
.ds-row-meta { display: flex; align-items: center; gap: 12px; margin: 12px 0 0; font-size: 0.8125rem; color: #5f6d75; }
.ds-dot { width: 4px; height: 4px; border-radius: 9999px; background: #ccd3d1; }
.ds-row-pdf { display: inline-flex; align-items: center; height: 36px; padding: 0 14px; border: 1px solid #ccd3d1; border-radius: 7px; background: transparent; color: #172b3a; font-size: 0.875rem; font-weight: 600; text-decoration: none; transition: border-color 160ms cubic-bezier(0.22, 1, 0.36, 1), background-color 160ms cubic-bezier(0.22, 1, 0.36, 1); }
.ds-row-pdf:hover { border-color: #24676b; background: #e9f1f0; color: #1c5559; }
.ds-row-pdf:focus-visible { outline: 2px solid #24676b; outline-offset: 2px; }

.ds-header { display: flex; align-items: center; gap: 32px; height: 80px; padding: 0 32px; border-bottom: 1px solid #e1e5e4; background: #faf9f6; font-family: 'Source Sans 3', system-ui, sans-serif; }
.ds-brand { font-family: 'Source Serif 4', Georgia, serif; font-size: 1.25rem; font-weight: 600; letter-spacing: -0.01em; color: #102a3a; text-decoration: none; }
.ds-nav { display: flex; gap: 24px; margin-left: auto; }
.ds-nav-link { position: relative; padding: 6px 0; color: #172b3a; font-size: 0.9375rem; text-decoration: none; }
.ds-nav-link:hover { color: #1c5559; }
.ds-nav-link--current::after { content: ''; position: absolute; left: 0; right: 0; bottom: -2px; height: 2px; background: #24676b; }
.ds-nav-link:focus-visible { outline: 2px solid #24676b; outline-offset: 2px; }
.ds-header-cta { display: inline-flex; align-items: center; height: 40px; padding: 0 18px; border-radius: 7px; background: #102a3a; color: #ffffff; font-size: 0.875rem; font-weight: 600; text-decoration: none; }
.ds-header-cta:hover { background: #0b1f2c; }
